<body class="intro-page" data-page="{{page}}">
  <a class="skip-link" href="#intro-main">Skip to content</a>
  <header class="site-header intro-header">
    <a class="brand" href="/" aria-current="page"><img class="bella-vista-mark" src="/assets/brand/bella-vista-mark.svg" alt="" width="42" height="42"><span><b>Bella Vista</b><small>Dining</small></span></a>
    <nav aria-label="Primary navigation"><a href="/#about">Our story</a><a href="/manage">My booking</a><a class="intro-nav-reserve" href="/reserve">Reserve a table <span aria-hidden="true">↗</span></a></nav>
  </header>
  <main id="intro-main" tabindex="-1">
    <section class="intro-hero" aria-labelledby="intro-title">
      <picture class="intro-backdrop" aria-hidden="true">
        <source media="(max-width: 700px)" srcset="/assets/images/intro/garden-estate-concept-small.webp" type="image/webp">
        <img src="/assets/images/intro/garden-estate-concept.webp" alt="" width="1672" height="941" loading="eager" fetchpriority="high">
      </picture>
      <div class="intro-shade" aria-hidden="true"></div>
      <div class="intro-garden" aria-hidden="true"><span class="garden-glow"></span><span class="garden-mote"></span><span class="garden-mote"></span><span class="garden-mote"></span><span class="garden-mote"></span><span class="garden-mote"></span><span class="garden-mote"></span><span class="garden-mote"></span></div>
      <div class="wrap intro-copy">
        <p class="eyebrow">A warm welcome to Bella Vista Dining</p>
        <h1 id="intro-title">Good food.<br><em>Better company.</em></h1>
        <p class="intro-lead">Filipino comfort food. Continental favourites.<br>A garden-inspired setting, made for gathering.</p>
        <div class="intro-actions"><a class="button intro-continue" id="booking" href="/reserve">Continue to reservation <svg width="22" height="22" viewBox="0 0 24 24" fill="none" aria-hidden="true"><path d="M4 12h15m-6-6 6 6-6 6" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round"/></svg></a><a class="intro-story-link" href="/#about">Get to know us <span aria-hidden="true">↓</span></a></div>
        <p class="intro-next-step">Choose your date, party size and table in the next step.</p>
      </div>
      <div class="wrap intro-caption"><p><span class="intro-caption-dot" aria-hidden="true"></span>Rooted in the garden. Made for the table.</p><button type="button" id="garden-toggle" class="garden-toggle" aria-label="Pause garden animation" title="Pause garden animation" hidden><svg width="18" height="18" viewBox="0 0 20 20" aria-hidden="true" fill="currentColor"><g class="garden-pause"><rect x="5" y="4" width="3" height="12" rx="1"/><rect x="12" y="4" width="3" height="12" rx="1"/></g><path class="garden-play" d="m6 3 10 7-10 7Z"/></svg></button></div>
    </section>
    <section class="section wrap company-section intro-about" id="about" aria-labelledby="about-title" tabindex="-1">
      <div class="company-intro"><p class="eyebrow">About Bella Vista</p><h2 id="about-title">A little escape.<br>A place to <em>gather.</em></h2><p class="company-lead">Bella Vista Dining is a premier farm-to-table restaurant offering a cozy, ambient, and modern dining experience.</p><p>It serves a fusion of local Filipino comfort food and continental specialties, designed for families, couples, and groups seeking a delightful culinary escape.</p><div class="company-links"><a class="text-link" href="/reserve#menu">Explore the menu <span aria-hidden="true">↗</span></a><a class="text-link" href="/#history">Read our history <span aria-hidden="true">↓</span></a></div></div>
      <aside class="company-emblem story-visual" aria-label="Bella Vista garden-estate concept">
        <figure class="story-photo story-dining"><picture><source media="(max-width: 700px)" srcset="/assets/images/intro/garden-interior-concept-small.webp" type="image/webp"><img src="/assets/images/intro/garden-interior-concept.webp" alt="Garden-estate dining room concept with brick arches, warm lamps, dark wood tables and greenery" width="1100" height="825" loading="lazy" decoding="async"></picture><figcaption>From the garden to your table.</figcaption></figure>
      </aside>
    </section>
    <section class="company-history section intro-history" id="history" aria-labelledby="history-title" tabindex="-1"><div class="wrap history-layout">
      <div class="history-heading"><p class="eyebrow">Our story</p><h2 id="history-title">A beginning worth<br><em>sharing.</em></h2><figure class="history-scene"><img src="/assets/images/intro/garden-estate-concept-small.webp" alt="Garden-estate restaurant concept with brick arches and warm evening lights" width="960" height="540" loading="lazy" decoding="async"><figcaption><span class="history-year">2021</span><span>Established alongside<br>the Bella Vista estate</span></figcaption></figure></div>
      <div class="history-copy"><ol class="story-timeline"><li><h3>The estate beginnings</h3><p class="company-lead">Established alongside the Bella Vista estate in 2021, the dining hall initially catered exclusively to in-house guests.</p></li><li><h3>A place of our own</h3><p>Due to overwhelming public demand for its signature dishes and scenic garden views, it expanded into an independent destination restaurant known for its exquisite food, ambient atmosphere, and exceptional customer service.</p></li></ol><p class="company-source">Company profile and history supplied in the restaurant brief for this academic project. The exterior above is an original concept visual.</p><a class="button ghost" href="/reserve">Find your table <span aria-hidden="true">↗</span></a><details class="story-photo-credits"><summary>About these images</summary><p>The exterior and matching interior are original AI-generated concept images for this academic project, not actual venue photographs or archival images from 2021.</p></details></div>
    </div></section>
  </main>
  <footer class="wrap intro-footer"><div><p class="eyebrow">Bella Vista Dining</p><p>Filipino comfort. Continental favourites.</p><small>Academic restaurant project · Philippines</small></div><nav aria-label="Footer navigation"><a href="/reserve">Table reservations</a><a href="/reserve#rooms">Explore the rooms</a><a href="/manage">Manage your booking</a><a href="/staff/login">Staff sign-in</a></nav></footer>
</body>
